import * as B from './engine.js';
import {COLUMNS} from './columns.js';
export const KINDS=['아파트','오피스텔','연립다세대','분양입주권','단독다가구','상업업무용','공장창고등'];
export function kindOf(s){const text=[s?.metadata?.['실거래 구분'],s?.name,s?.sheetName].join(' ');return KINDS.find(k=>text.includes(k))||(s?.headers?.includes('건물명')?'연립다세대':s?.headers?.includes('분양권/입주권')?'분양입주권':s?.headers?.includes('연면적(㎡)')?'단독다가구':'아파트');}
export const special=k=>KINDS.slice(2).includes(k);
export const broad=k=>KINDS.slice(4).includes(k);
export function parseRows(source){const kind=kindOf(source);if(!special(kind))return B.parseRows(source);
 const h=source.headers,get=(r,k)=>{const i=h.findIndex(v=>B.header(v)===k||B.header(v).startsWith(k+'('));return B.clean(r.cells[i]);};
 return source.rows.map((r,i)=>{const g=k=>get(r,k),addr=g('시군구'),region=B.district(addr),dong=B.dong(addr),category=kind==='분양입주권'?g('분양권/입주권'):kind==='연립다세대'||kind==='단독다가구'?g('주택유형'):g('유형'),usage=g('건축물주용도'),floor=g('층')||'미기재',area=B.number(g(broad(kind)?kind==='단독다가구'?'연면적':'전용/연면적':'전용면적')),landArea=B.number(g(kind==='연립다세대'?'대지권면적':'대지면적')),price=B.number(g('거래금액')),address=B.clean(addr+' '+(g('번지')||g('지번'))),broker=g('중개사소재지');
 const name=broad(kind)?[dong,category,usage,...(kind==='단독다가구'?[]:[floor==='미기재'?'층 미기재':floor+'층'])].filter(Boolean).join(' · '):(g('건물명')||g('단지명'));const type=kind==='분양입주권'?Math.floor(area):kind==='연립다세대'?area:0;
 let reason='포함';if(g('해제사유발생일')&&g('해제사유발생일')!=='-')reason='해제 거래';else if(!region||!name||!Number.isFinite(price)||price<=0||price>1e12)reason='입력값 확인';else if(g('지분구분')==='지분')reason='지분 거래';else if(g('거래유형')==='직거래')reason='직거래';else if(g('거래유형')!=='중개거래')reason='거래유형 확인';else {const brokers=broker.split(/[,，;]/).map(B.district);if(!brokers.length||brokers.some(x=>!x))reason='소재지 미확인';else if(brokers.some(x=>x!==region))reason='타지역 중개사';}
 return {id:'raw-'+r.rowNumber+'-'+i,cells:r.cells,rowNumber:r.rowNumber,kind,name,category,usage,floor,area,landArea,price,type,address,sourceAddress:addr,region,dong,regionKey:region+' '+dong,year:B.yearKey(g('건축년도')),date:B.contractDate(g('계약년월'),g('계약일')),broker,reason,road:g('도로조건')||'미기재',zone:g('용도지역')||'미기재',roadAddress:g('도로명'),share:g('지분구분')||'일반',unitPrice:area>0?price/area*B.SQM_PER_PYEONG:null,landUnitPrice:landArea>0&&category!=='집합'?price/landArea*B.SQM_PER_PYEONG:null};});
}
export function propertyKey(r){return special(r.kind)?JSON.stringify(broad(r.kind)?[r.kind,r.region,r.dong,r.category,r.usage,r.floor]:[r.kind,r.name,r.address,r.category]):B.propertyKey(r);}
export function reviewKey(r){return special(r.kind)?JSON.stringify([propertyKey(r),r.type]):B.reviewKey(r);}
export function salePolicyRows(rows,p={}){return rows.map(r=>{if(!special(r.kind))return B.salePolicyRows([r],p)[0];if((r.reason==='직거래'&&p.direct)||(r.reason==='타지역 중개사'&&p.outside))return {...r,reason:'포함'};return r;});}
export function filtered(rows,f={}){return B.filtered(rows,f).filter(r=>['category','usage','floor','zone','road'].every(k=>f[k]==null||f[k].has(r[k])));}
const groups=(rows,key)=>{const m=new Map();for(const r of rows){const k=key(r);if(!m.has(k))m.set(k,[]);m.get(k).push(r);}return [...m.values()];};
function stat(rows,key){const v=rows.map(r=>r[key]).filter(Number.isFinite);return v.length?[Math.min(...v),Math.max(...v),v.reduce((a,b)=>a+b,0)/v.length]:[null,null,null];}
function summary(rows){const [priceMinimum,priceMaximum,priceAverage]=stat(rows,'price'),[minimum,maximum,average]=stat(rows,'unitPrice'),[landMinimum,landMaximum,landAverage]=stat(rows,'landUnitPrice'),[areaMin,areaMax]=stat(rows,'area');return {priceMinimum,priceMaximum,priceAverage,minimum,maximum,average,landMinimum,landMaximum,landAverage,areaMin,areaMax,count:rows.length,pricedCount:rows.filter(r=>Number.isFinite(r.price)).length,areaText:areaMin>0?B.range(areaMin,areaMax,'㎡'):'-',pyeongText:areaMin>0?B.range(areaMin/B.SQM_PER_PYEONG,areaMax/B.SQM_PER_PYEONG,'평',2):'-'};}
export function aggregate(rows){if(!rows.some(r=>special(r.kind)))return B.aggregate(rows);const included=rows.filter(r=>r.reason==='포함'),excluded=rows.filter(r=>r.reason!=='포함'),make=(items,id)=>({...items[0],...summary(items),id,year:[...new Set(items.map(r=>r.year))].join(', '),typeText:items[0].type+'타입'});
 const apartments=groups(included,reviewKey).map(g=>make(g,reviewKey(g[0]))).sort((a,b)=>a.name.localeCompare(b.name,'ko',{numeric:true})||a.type-b.type);
 const districts=groups(included,r=>JSON.stringify(broad(r.kind)?[r.region,r.dong,r.category,r.usage,r.floor]:[r.region,r.dong,r.category,r.name,r.address])).map(g=>make(g,'district-'+propertyKey(g[0])));
 const reasons={};for(const r of excluded)reasons[r.reason]=(reasons[r.reason]||0)+1;return {included,excluded,apartments,districts,reasons,total:rows.length};}
export function trend(rows,key,type=null,frequency='month'){if(!rows.some(r=>special(r.kind)))return B.trend(rows,key,type,frequency);const trades=rows.filter(r=>r.reason==='포함'&&propertyKey(r)===key&&(type==null||String(r.type)===String(type))).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));const points=groups(trades.filter(r=>r.date&&Number.isFinite(r.unitPrice)),r=>frequency==='month'?r.date.slice(0,7):r.date).map(g=>({date:frequency==='month'?g[0].date.slice(0,7):g[0].date,average:summary(g).average,count:g.length}));return {trades,points,missing:trades.filter(r=>!r.date).length};}
export function periodAnalysis(rows,scope='property',frequency='month',from=null,to=null){if(!rows.some(r=>special(r.kind)))return B.periodAnalysis(rows,scope,frequency,from,to);const dates=rows.map(r=>r.date).filter(Boolean).sort();from=from||dates[0];to=to||dates.at(-1);const periods=[];if(from&&to)for(let d=new Date(from.slice(0,7)+'-01T00:00:00Z');d.toISOString().slice(0,10)<=to;d.setUTCMonth(d.getUTCMonth()+1)){const p=B.periodLabel(d.toISOString().slice(0,10),frequency);if(!periods.includes(p))periods.push(p);}
 const key=r=>scope==='dong'?JSON.stringify([r.region,r.dong,r.category,r.usage,broad(r.kind)?r.floor:null,r.type]):reviewKey(r);const result=[];
 for(const g of groups(rows.filter(r=>r.date&&r.date>=from&&r.date<=to),key)){const r=g[0],targetKey=scope==='dong'?JSON.stringify([r.region,r.dong,r.category,r.usage,broad(r.kind)?r.floor:null]):propertyKey(r);for(const period of periods){const items=g.filter(t=>t.reason==='포함'&&B.periodLabel(t.date,frequency)===period);result.push({...r,...summary(items),id:JSON.stringify([key(r),period]),groupKey:key(r),targetKey,group:scope==='dong'?[r.region,r.dong,r.category,r.usage].filter(Boolean).join(' · '):r.name,period,typeText:r.type+'타입'});}}
 return {rows:result.sort((a,b)=>a.group.localeCompare(b.group,'ko',{numeric:true})||a.type-b.type||a.period.localeCompare(b.period)),missing:rows.filter(r=>r.reason==='포함'&&!r.date).length};}
export function mergeSources(sources,dedupe=true){if(sources.some(s=>kindOf(s)!==kindOf(sources[0])))throw Error('다른 부동산 유형은 별도로 집계해야 합니다.');const masked=sources.some(s=>s.rows.some(r=>r.cells.some(v=>/\*/.test(String(v)))));const out=B.mergeSources(sources,masked?false:dedupe);return {...out,masked,duplicates:masked?0:out.duplicates,duplicateCandidates:masked?out.duplicates:0};}
const c=(key,label,numeric=false,width=115)=>({key,label,numeric,width,value:r=>r[key]});
const amount=[c('priceMinimum','최소 거래금액',true),c('priceMaximum','최대 거래금액',true),c('priceAverage','평균 거래금액',true)];
const prices=prefix=>['minimum','maximum','average'].map((key,i)=>({...c(key,['최소 ','최대 ','평균 '][i]+prefix+'평당가',true,145),roundCopy:true}));
const land=['landMinimum','landMaximum','landAverage'].map((key,i)=>({...c(key,['최소 ','최대 ','평균 '][i]+'대지 평당가',true,140),roundCopy:true}));
export function columns(kind){if(!special(kind))return COLUMNS;const isBroad=broad(kind),nonres=['상업업무용','공장창고등'].includes(kind),category=c('category',kind==='분양입주권'?'권리구분':nonres?'건물유형':'주택유형'),floor=c('floor','층',false,80),usage=c('usage','건축물주용도',false,160),count={...c('count','거래 건수',true,100),value:r=>r.count||null};
 const mainBase=isBroad?[{...c('name','행정동',false,120),value:r=>r.dong},c('region','시군구'),category,...(nonres?[usage,floor]:[])]:[c('name',kind==='연립다세대'?'건물명':'단지명',false,170),category,...(kind==='연립다세대'?[c('year','건축년도')]:[]),c('dong','행정동'),c('region','시군구'),c('address','주소',false,100),...COLUMNS.apartments.slice(5,7),...(kind==='분양입주권'?[COLUMNS.apartments[7]]:[])];
 const metrics=isBroad?[...amount,...land,...prices(nonres?'전용/연면적 ':'연면적 ')]:[...prices(''),...amount];
 const cases=[c('date','계약일'),c('name',isBroad?'집계 대상':'건물·단지명',false,160),c('address','주소',false,190),category,...(nonres?[usage]:[]),c('year','건축년도'),floor,c('area',isBroad?nonres?'전용/연면적(㎡)':'연면적(㎡)':'전용면적(㎡)',true,140),c('landArea',kind==='연립다세대'?'대지권면적(㎡)':'대지면적(㎡)',true,130),c('price','거래금액',true),{...c('unitPrice',isBroad?'건물면적 평당가':'평당가',true,140),roundCopy:true},...(isBroad?[c('landUnitPrice','대지 평당가',true),c('road','도로조건'),...(nonres?[c('zone','용도지역'),c('share','지분구분')]:[])]:[])];
 const result={apartments:[...mainBase,...metrics,count],districts:[c('dong','행정동'),c('region','시군구'),...(!isBroad?[c('name',kind==='연립다세대'?'건물명':'단지명',false,170),c('address','주소',false,100)]:[]),category,...(nonres?[usage,floor]:[]),...metrics,count],periods:[c('period','기간'),c('group','집계 대상',false,210),category,...(nonres?[usage,floor]:[]),...(kind==='분양입주권'?[COLUMNS.apartments[7]]:kind==='연립다세대'?[c('area','전용면적(㎡)',true,130)]:[]),...metrics,count],cases,excluded:[...cases,c('broker','중개사 소재지',false,160),c('reason','제외 사유',false,140)]};
 for(const cols of Object.values(result))for(const col of cols)if(col.numeric)col.exportLabel=col.label+(col.label.includes('평당가')?'(만원/평)':col.key.startsWith('price')?'(만 원)':'');return result;
}
export function sourceText(s){if(!special(kindOf(s)))return B.sourceText(s);return B.sourceText(s).replace('÷ 전용면적(㎡)','÷ 해당 전용·연면적 또는 대지면적(㎡)')+'\n면적 기준: 일반건물은 연면적, 집합건물은 전용면적. 대지·건물면적 평당가는 전체 거래금액을 나눈 값이며 순수 토지·건물 가격이 아닙니다.\n지분 거래는 별도 제외. 면적 미기재는 해당 평당가만 제외하며 거래금액·건수는 유지합니다.'+(s.masked?'\n주소 일부 비공개: 같은 건물로 추정하지 않습니다. 파일 간 동일행은 중복 의심으로 보존합니다.':'');}
